create function public.host_picture_caption_reveal_projection(p_host_id uuid,p_party_id uuid) returns table(reveal_position integer,voter_nickname text,voter_color text,candidate_caption text,game_session_id uuid,session_revision bigint) language sql stable security definer set search_path='' as $$ select row_number() over(order by md5(round.id::text||ballot.id::text))::integer-1,voter.nickname,voter.color,candidate.caption,session.id,session.revision from public.parties party join public.game_sessions session on session.id=party.current_game_session_id join public.picture_caption_rounds round on round.game_session_id=session.id and round.state='active' and round.phase='revealing' join public.picture_caption_ballots ballot on ballot.round_id=round.id join public.party_members voter on voter.id=ballot.party_member_id join public.picture_caption_candidates candidate on candidate.id=ballot.candidate_id where party.host_id=p_host_id and party.id=p_party_id order by 1; $$;
create function public.display_picture_caption_reveal_projection(p_display_session_id uuid,p_party_code text) returns table(reveal_position integer,voter_nickname text,voter_color text,candidate_caption text,game_session_id uuid,session_revision bigint) language sql stable security definer set search_path='' as $$ select row_number() over(order by md5(round.id::text||ballot.id::text))::integer-1,voter.nickname,voter.color,candidate.caption,session.id,session.revision from public.display_sessions display_session join public.parties party on party.id=display_session.party_id join public.game_sessions session on session.id=party.current_game_session_id join public.picture_caption_rounds round on round.game_session_id=session.id and round.state='active' and round.phase='revealing' join public.picture_caption_ballots ballot on ballot.round_id=round.id join public.party_members voter on voter.id=ballot.party_member_id join public.picture_caption_candidates candidate on candidate.id=ballot.candidate_id where display_session.id=p_display_session_id and display_session.revoked_at is null and party.code=upper(trim(p_party_code)) order by 1; $$;
create function public.player_picture_caption_reveal_projection(p_player_id uuid,p_party_code text) returns table(reveal_position integer,voter_nickname text,voter_color text,candidate_caption text,game_session_id uuid,session_revision bigint) language sql stable security definer set search_path='' as $$ select row_number() over(order by md5(round.id::text||ballot.id::text))::integer-1,voter.nickname,voter.color,candidate.caption,session.id,session.revision from public.parties party join public.game_sessions session on session.id=party.current_game_session_id join public.picture_caption_rounds round on round.game_session_id=session.id and round.state='active' and round.phase='revealing' join public.picture_caption_ballots ballot on ballot.round_id=round.id join public.party_members voter on voter.id=ballot.party_member_id join public.picture_caption_candidates candidate on candidate.id=ballot.candidate_id where party.code=upper(trim(p_party_code)) and exists(select 1 from public.party_members member where member.player_id=p_player_id and member.party_id=party.id) order by 1; $$;
create function public.picture_caption_results_projection(p_party_id uuid) returns table(caption text,points integer,is_leader boolean,author_nickname text,author_color text,game_session_id uuid,session_revision bigint) language sql stable security definer set search_path='' as $$ select candidate.caption,candidate.points,candidate.points=(select max(other.points) from public.picture_caption_candidates other where other.round_id=round.id),author.nickname,author.color,session.id,session.revision from public.parties party join public.game_sessions session on session.id=party.current_game_session_id join public.picture_caption_rounds round on round.game_session_id=session.id and round.state='active' and round.phase in ('revealing','results') join public.picture_caption_candidates candidate on candidate.round_id=round.id join public.picture_caption_candidate_authors candidate_author on candidate_author.candidate_id=candidate.id join public.party_members author on author.id=candidate_author.party_member_id where party.id=p_party_id order by candidate.points desc,candidate.display_position,author.nickname; $$;
revoke all on function public.host_picture_caption_reveal_projection(uuid,uuid),public.display_picture_caption_reveal_projection(uuid,text),public.player_picture_caption_reveal_projection(uuid,text),public.picture_caption_results_projection(uuid) from public,anon,authenticated;
grant execute on function public.host_picture_caption_reveal_projection(uuid,uuid),public.display_picture_caption_reveal_projection(uuid,text),public.player_picture_caption_reveal_projection(uuid,text),public.picture_caption_results_projection(uuid) to service_role;